5492	static int smu7_odn_edit_dpm_table(struct pp_hwmgr *hwmgr,
5493						enum PP_OD_DPM_TABLE_COMMAND type,
5494						long *input, uint32_t size)
5495	{
5496		uint32_t i;
5497		struct phm_odn_clock_levels *podn_dpm_table_in_backend = NULL;
5498		struct smu7_odn_clock_voltage_dependency_table *podn_vdd_dep_in_backend = NULL;
5499		struct smu7_hwmgr *data = (struct smu7_hwmgr *)(hwmgr->backend);
5500	
5501		uint32_t input_clk;
5502		uint32_t input_vol;
5503		uint32_t input_level;
5504	
5505		PP_ASSERT_WITH_CODE(input, "NULL user input for clock and voltage",
5506					return -EINVAL);
5507	
5508		if (!hwmgr->od_enabled) {
5509			pr_info("OverDrive feature not enabled\n");
5510			return -EINVAL;
5511		}
5512	
5513		if (PP_OD_EDIT_SCLK_VDDC_TABLE == type) {
5514			podn_dpm_table_in_backend = &data->odn_dpm_table.odn_core_clock_dpm_levels;
5515			podn_vdd_dep_in_backend = &data->odn_dpm_table.vdd_dependency_on_sclk;
5516			PP_ASSERT_WITH_CODE((podn_dpm_table_in_backend && podn_vdd_dep_in_backend),
5517					"Failed to get ODN SCLK and Voltage tables",
5518					return -EINVAL);
5519		} else if (PP_OD_EDIT_MCLK_VDDC_TABLE == type) {
5520			podn_dpm_table_in_backend = &data->odn_dpm_table.odn_memory_clock_dpm_levels;
5521			podn_vdd_dep_in_backend = &data->odn_dpm_table.vdd_dependency_on_mclk;
5522	
5523			PP_ASSERT_WITH_CODE((podn_dpm_table_in_backend && podn_vdd_dep_in_backend),
5524				"Failed to get ODN MCLK and Voltage tables",
5525				return -EINVAL);
5526		} else if (PP_OD_RESTORE_DEFAULT_TABLE == type) {
5527			smu7_odn_initial_default_setting(hwmgr);
5528			return 0;
5529		} else if (PP_OD_COMMIT_DPM_TABLE == type) {
5530			smu7_check_dpm_table_updated(hwmgr);
5531			return 0;
5532		} else {
5533			return -EINVAL;
5534		}
5535	
5536		for (i = 0; i < size; i += 3) {
5537			if (i + 3 > size || input[i] >= podn_dpm_table_in_backend->num_of_pl) {
5538				pr_info("invalid clock voltage input \n");
5539				return 0;
5540			}
5541			input_level = input[i];
5542			input_clk = input[i+1] * 100;
5543			input_vol = input[i+2];
5544	
5545			if (smu7_check_clk_voltage_valid(hwmgr, type, input_clk, input_vol)) {
5546				podn_dpm_table_in_backend->entries[input_level].clock = input_clk;
5547				podn_vdd_dep_in_backend->entries[input_level].clk = input_clk;
5548				podn_dpm_table_in_backend->entries[input_level].vddc = input_vol;
5549				podn_vdd_dep_in_backend->entries[input_level].vddc = input_vol;
5550				podn_vdd_dep_in_backend->entries[input_level].vddgfx = input_vol;
5551			} else {
5552				return -EINVAL;
5553			}
5554		}
5555	
5556		return 0;
5557	}
