5559	static int smu7_get_power_profile_mode(struct pp_hwmgr *hwmgr, char *buf)
5560	{
5561		struct smu7_hwmgr *data = (struct smu7_hwmgr *)(hwmgr->backend);
5562		uint32_t i, size = 0;
5563		uint32_t len;
5564	
5565		static const char *title[8] = {"NUM",
